//! `sp_engine::tower` reproduces the Tower mockup exactly (ENG-5, TW-2, TW-6, TW-7, DONE-2).
//!
//! `tower_goldens.json` holds what `docs/design/mockup/Tower.dc.html`'s own `calc()` and
//! `renderVals()` produce for 110 states (the default, every system × shape, floors and wind
//! edges, the damper, lock-in states and a seeded sample), generated by
//! `node crates/sp-engine/tests/tower_ground_goldens.mjs`.

use serde_json::Value;
use sp_engine::jsnum::fixed;
use sp_engine::tower::{self, Shape, Status, System, TowerInput};

fn goldens() -> Vec<Value> {
    serde_json::from_str(include_str!("tower_goldens.json")).expect("valid golden JSON")
}

fn input_of(st: &Value) -> TowerInput {
    TowerInput {
        floors: st["floors"].as_u64().unwrap() as u32,
        system: System::from_key(st["sys"].as_str().unwrap()).unwrap(),
        shape: Shape::from_key(st["shape"].as_str().unwrap()).unwrap(),
        v10: st["v10"].as_f64().unwrap(),
        damper: st["damper"].as_bool().unwrap(),
    }
}

fn close(a: f64, b: f64, what: &str, ctx: &str) {
    let tol = 1e-12 * a.abs().max(b.abs()).max(1e-300);
    assert!((a - b).abs() <= tol, "{ctx}: {what} {a} vs mockup {b}");
}

#[test]
fn every_golden_state_matches_the_mockup() {
    let all = goldens();
    assert!(all.len() >= 100, "{} states", all.len());
    for g in &all {
        let input = input_of(&g["state"]);
        let ctx = format!("{:?}", g["state"]);
        let r = tower::calc(&input);
        let c = &g["calc"];
        close(r.height, c["H"].as_f64().unwrap(), "H", &ctx);
        close(r.base_shear, c["V"].as_f64().unwrap(), "V", &ctx);
        close(r.overturning, c["M"].as_f64().unwrap(), "M", &ctx);
        close(r.delta, c["delta"].as_f64().unwrap(), "delta", &ctx);
        close(r.f1, c["f1"].as_f64().unwrap(), "f1", &ctx);
        close(r.mg, c["mg"].as_f64().unwrap(), "mg", &ctx);
        close(r.v_top, c["vH"].as_f64().unwrap(), "vH", &ctx);
        close(r.fs, c["fs"].as_f64().unwrap(), "fs", &ctx);
        close(r.ratio, c["ratio"].as_f64().unwrap(), "ratio", &ctx);
        assert_eq!(r.lock, c["lock"].as_bool().unwrap(), "{ctx}: lock");
        let near = c["near"].as_f64().unwrap();
        assert!(
            (r.near - near).abs() <= 1e-9,
            "{ctx}: near {} vs {near}",
            r.near
        );
        close(r.cost, c["cost"].as_f64().unwrap(), "cost", &ctx);
        close(r.dyn_amp, c["dyn"].as_f64().unwrap(), "dyn", &ctx);

        // Tiles.
        let tiles = tower::tiles(&r);
        for (t, gt) in tiles.iter().zip(g["tiles"].as_array().unwrap()) {
            assert_eq!(t.key, gt["k"], "{ctx}");
            assert_eq!(t.value, gt["v"], "{ctx}: {}", t.key);
            assert_eq!(t.note, gt["n"], "{ctx}: {}", t.key);
            assert_eq!(t.tone.css(), gt["c"], "{ctx}: {} colour", t.key);
        }
        // Status, comfort.
        let status = Status::of(&r);
        assert_eq!(status.label(), g["status"], "{ctx}");
        assert_eq!(status.tone().css(), g["statusColor"], "{ctx}");
        assert_eq!(tower::accel_label(&r), g["accel"], "{ctx}");
        assert_eq!(fixed(tower::comfort_pos(r.mg), 1), g["comfortPos"], "{ctx}");
        let comfort = tower::Comfort::of(r.mg);
        assert_eq!(comfort.sentence(), g["comfortText"], "{ctx}");
        assert_eq!(comfort.tone().css(), g["comfortColor"], "{ctx}");
        // Same storm, four shapes.
        let bars = tower::compare(&input);
        for (b, gb) in bars.iter().zip(g["compare"].as_array().unwrap()) {
            assert_eq!(b.shape.def().name, gb["name"], "{ctx}");
            assert_eq!(b.label(), gb["v"], "{ctx}");
            assert_eq!(fixed(b.width, 0), gb["w"], "{ctx}: width of {}", gb["name"]);
            assert_eq!(b.tone().css(), gb["color"], "{ctx}");
            let selected = gb["tc"] == "#F5F5F5";
            assert_eq!(b.shape == input.shape, selected, "{ctx}");
        }
        // Goals. The second is SPEC MB-6's H/350 (the mockup's H/500 is unreachable at 100
        // floors); checked against the mockup's own drift numbers.
        let goals = tower::goals(&input, &r);
        for (i, (gl, gg)) in goals.iter().zip(g["goals"].as_array().unwrap()).enumerate() {
            if i == 1 {
                assert_eq!(gl.text, "Drift better than H/350 at 30 m/s", "{ctx}");
                let drift = c["H"].as_f64().unwrap() / c["delta"].as_f64().unwrap();
                let storm = g["state"]["v10"].as_f64().unwrap() >= 30.0;
                assert_eq!(gl.done, storm && drift >= 350.0, "{ctx}: MB-6 drift goal");
                continue;
            }
            assert_eq!(gl.text, gg["text"], "{ctx}");
            assert_eq!(gl.done, gg["done"].as_bool().unwrap(), "{ctx}: {}", gl.text);
        }
        // Sentences and labels.
        assert_eq!(tower::explain(&input, &r), g["explain"], "{ctx}");
        assert_eq!(tower::sway_chip(&r), g["swayChip"], "{ctx}");
        assert_eq!(tower::v_top_label(&r), g["vTop"], "{ctx}");
        assert_eq!(tower::v10_label(input.v10), g["v10Label"], "{ctx}");
        assert_eq!(tower::clock(&r), g["clock"], "{ctx}");
        assert_eq!(tower::stage_label(&input, &r), g["stageLabel"], "{ctx}");
        assert_eq!(r.height, g["height"].as_f64().unwrap(), "{ctx}");
    }
}

/// The numbers in the reference screenshot `docs/design/screenshots/Tower-1440.png`.
#[test]
fn the_default_state_shows_the_reference_numbers() {
    let input = TowerInput::default();
    let r = tower::calc(&input);
    let tiles = tower::tiles(&r);
    let values: Vec<&str> = tiles.iter().map(|t| t.value.as_str()).collect();
    assert_eq!(
        values,
        ["928 mm", "9.9 s", "19.0 MN", "2.64 GN·m", "1.69×", "$60M"]
    );
    assert_eq!(tiles[0].note, "drift H/259 · aim H/500");
    assert_eq!(tiles[1].note, "0.101 Hz");
    assert_eq!(tower::accel_label(&r), "9.5 milli-g");
    assert_eq!(tower::sway_chip(&r), "top 928 mm · H/259");
    assert_eq!(tower::v_top_label(&r), "57 m/s · 127 mph");
    assert_eq!(tower::v10_label(30.0), "30 m/s · 67 mph");
    assert_eq!(tower::clock(&r), "T = 9.9 s");
    assert_eq!(tower::floors_note(&input), "floors · 240 m");
    assert_eq!(Status::of(&r).label(), "Too much sway");
    let bars: Vec<String> = tower::compare(&input).iter().map(|b| b.label()).collect();
    assert_eq!(bars, ["9.5 mg", "6.6 mg", "7.8 mg", "7.4 mg"]);
    let done: Vec<bool> = tower::goals(&input, &r).iter().map(|g| g.done).collect();
    assert_eq!(done, [false, false, true, true]);
}

/// SPEC MB-6 / DONE-4: the challenge can be completed. `tower::CHALLENGE_DESIGN` — 100 floors, a
/// braced tapered tube with the tuned mass damper, 30 m/s — meets all four goals at once (drift
/// H/367 against the H/350 goal, 4.4 milli-g, $144M). The mockup's H/500 is out of reach for
/// every 100-floor tower in the (exact) model, which is why the goal moved; H/350 is the lowest
/// round threshold (multiples of 50) that a complete design meets.
#[test]
fn the_100_floor_challenge_is_completable() {
    let input = tower::CHALLENGE_DESIGN;
    assert_eq!(
        (
            input.floors,
            input.system,
            input.shape,
            input.v10,
            input.damper
        ),
        (100, System::Braced, Shape::Tapered, 30.0, true)
    );
    let r = tower::calc(&input);
    let goals = tower::goals(&input, &r);
    assert!(goals.iter().all(|g| g.done), "{goals:?}");
    assert_eq!(sp_engine::jsnum::round_str(r.drift_ratio()), "367");
    assert_eq!(tower::accel_label(&r), "4.4 milli-g");
    assert_eq!(fixed(r.cost, 0), "144");
    // The tile still aims at H/500 (and the status says so).
    assert_eq!(tower::tiles(&r)[0].note, "drift H/367 · aim H/500");
    assert_eq!(Status::of(&r), Status::TooMuchSway);

    // Every 100-floor design in the storm: none reaches H/500; the complete ones (all four
    // goals with the threshold relaxed) top out at H/367, so H/350 is the lowest round bar.
    let designs: Vec<TowerInput> = System::ALL
        .into_iter()
        .flat_map(|system| {
            Shape::ALL.into_iter().flat_map(move |shape| {
                [false, true].map(|damper| TowerInput {
                    floors: 100,
                    system,
                    shape,
                    v10: 30.0,
                    damper,
                })
            })
        })
        .collect();
    let best_complete = designs
        .iter()
        .map(|d| (d, tower::calc(d)))
        .filter(|(_, r)| r.comfort_ok() && r.within_budget())
        .map(|(_, r)| r.drift_ratio())
        .fold(0.0, f64::max);
    assert!(best_complete < tower::DRIFT_AIM, "H/{best_complete:.0}");
    assert!((tower::DRIFT_GOAL..400.0).contains(&best_complete));
    assert_eq!(tower::DRIFT_GOAL, 350.0);
}

#[test]
fn share_line_is_one_story_line() {
    let input = TowerInput::default();
    let r = tower::calc(&input);
    let s = tower::share_line(&input, &r);
    assert_eq!(
        s,
        ".story 60 4 1600t core shape=straight damper=off  .wind 30 0.2  ; top 928 mm · H/259 · \
         T = 9.9 s · 9.5 milli-g"
    );
    assert!(!s.contains('\n'));
}
